package com.smartmanager.nativeapp;
import android.content.*;import android.util.Base64;import java.nio.charset.StandardCharsets;import java.security.KeyStore;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** Encrypted multi-router profile store. Metadata and passwords share one authenticated archive. */
public final class RouterProfilesStore {public static final class Profile{public final String id,name,host,port,user,password;public final boolean tls;Profile(String i,String n,String h,String p,String u,String pw,boolean t){id=i;name=n;host=h;port=p;user=u;password=pw;tls=t;}}
 private static final String ALIAS="smart_manager_profiles_key",PREF="router_profiles";private final SharedPreferences prefs;public RouterProfilesStore(Context c){prefs=c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}public synchronized List<Profile> all()throws Exception{String raw=decrypt();List<Profile> out=new ArrayList<>();if(raw.isEmpty())return out;for(String l:raw.split("\\n")){String[] x=l.split("\\|",-1);if(x.length!=7)throw new java.io.IOException("Corrupt router profile archive");out.add(new Profile(x[0],dec(x[1]),dec(x[2]),x[3],dec(x[4]),dec(x[5]),"1".equals(x[6])));}return out;}public synchronized void upsert(Profile p)throws Exception{List<Profile> a=all();boolean found=false;for(int i=0;i<a.size();i++)if(a.get(i).id.equals(p.id)){a.set(i,p);found=true;}if(!found)a.add(p);save(a);}public synchronized void remove(String id)throws Exception{List<Profile>a=all();a.removeIf(p->p.id.equals(id));save(a);}private void save(List<Profile>a)throws Exception{StringBuilder b=new StringBuilder();for(Profile p:a)b.append(p.id).append('|').append(enc(p.name)).append('|').append(enc(p.host)).append('|').append(p.port).append('|').append(enc(p.user)).append('|').append(enc(p.password)).append('|').append(p.tls?1:0).append('\n');encrypt(b.toString());}private String decrypt()throws Exception{String v=prefs.getString("archive",null);if(v==null)return "";String[]p=v.split("\\.",2);if(p.length!=2)throw new java.io.IOException("Corrupt router profile archive");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p[0],2)));return new String(c.doFinal(Base64.decode(p[1],2)),StandardCharsets.UTF_8);}private void encrypt(String raw)throws Exception{byte[]iv=new byte[12];new java.security.SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(),new GCMParameterSpec(128,iv));if(!prefs.edit().putString("archive",Base64.encodeToString(iv,2)+"."+Base64.encodeToString(c.doFinal(raw.getBytes(StandardCharsets.UTF_8)),2)).commit())throw new java.io.IOException("Profile storage full");}private SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(s.containsAlias(ALIAS))return((KeyStore.SecretKeyEntry)s.getEntry(ALIAS,null)).getSecretKey();KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new android.security.keystore.KeyGenParameterSpec.Builder(ALIAS,3).setBlockModes("GCM").setEncryptionPaddings("NoPadding").setRandomizedEncryptionRequired(true).build());return g.generateKey();}private static String enc(String s){return Base64.encodeToString((s==null?"":s).getBytes(StandardCharsets.UTF_8),2);}private static String dec(String s){return new String(Base64.decode(s,2),StandardCharsets.UTF_8);}}
